class City:
    postcodes = {'Helsinki': '00100', 'Turku': '20100', 'Tampere': '33100', 'Jyväskylä': '40100', 'Oulu': '40100'}

    def __init__(self, name: str, population: int):
        self.name = name
        self.population = population

    def __str__(self):
        return f"{self.name} ({self.population})"

